    request.setFormaPagamento(FormaPagamento.CARTAO);
    request.setParcelas(3);
    request.setNivelClube(NivelClube.PRATA);
    request.setRegiao(Regiao.SUL);

    CheckoutResponse response = checkoutService.calcularResumo(request);

